<?php
declare(strict_types=1);

require_once __DIR__ . '/IdiomaService.php';

/**
 * Não Conformidades — textos das telas em português, inglês e espanhol (auditoria de idiomas, 18/11/2026).
 * Cada texto vira a chave naoconformidades.<chave> em Administração › Textos e idiomas, onde pode ser corrigido;
 * aqui fica só o padrão. Os valores gravados no banco (etapa, situação) continuam em português: etapa() e valor()
 * traduzem só o que aparece na tela.
 */
final class NaoConformidadeTextos
{
    public const GRUPO = 'naoconformidades';

    public static function t(string $chave, array $valores = []): string
    {
        $d = self::TEXTOS[$chave] ?? [$chave, $chave, $chave];
        return IdiomaService::f(self::GRUPO . '.' . $chave, ['pt' => $d[0], 'en' => $d[1], 'es' => $d[2]], $valores);
    }

    /**
     * Texto em português usado como rótulo (relatório/PDF da NC): devolve a tradução da primeira chave com esse texto
     * (rótulos das abas, colunas, histórico) ou o próprio texto quando não há chave.
     */
    public static function porTexto(string $pt): string
    {
        static $indice = null;
        if ($pt === '' || IdiomaService::idioma() === 'pt') return $pt;
        if ($indice === null) { $indice = []; foreach (self::TEXTOS as $k => $d) if (!str_contains($d[0], '{')) $indice[$d[0]] ??= $k; }
        return isset($indice[$pt]) ? self::t($indice[$pt]) : $pt;
    }

    /** Itens com o prefixo pedido (ex.: 'rel.') para registrar no banco (scripts/aplicar-onda2-banco-idiomas.php). */
    public static function itensIdioma(string $prefixo): array
    {
        $itens = []; $o = 0;
        foreach (self::TEXTOS as $k => [$pt, $en, $es]) if (str_starts_with($k, $prefixo)) $itens[] = ['chave' => self::GRUPO . '.' . $k, 'tipo' => 'TEXTO', 'ordem' => 9000 + ++$o, 'descricao' => 'Relatório/PDF da não conformidade', 'pt' => $pt, 'en' => $en, 'es' => $es];
        return $itens;
    }

    /** Etapas e situações gravadas em português (inclui a grafia sem acento do legado): devolve o texto traduzido. */
    public static function valor(?string $v): string
    {
        $v = (string)$v;
        if ($v === '' || IdiomaService::idioma() === 'pt') return $v;
        $n = self::normal($v);
        foreach (self::TEXTOS as $k => $d) if (str_starts_with($k, 'valor.') && self::normal($d[0]) === $n) return self::t($k);
        return $v;
    }

    /** [valor gravado normalizado => texto traduzido] (para o JavaScript dos grids). */
    public static function valores(): array
    {
        $out = [];
        foreach (self::TEXTOS as $k => $d) if (str_starts_with($k, 'valor.')) $out[$d[0]] = self::t($k);
        return $out;
    }

    private static function normal(string $v): string
    {
        $v = mb_strtolower(trim($v));
        return strtr($v, ['á' => 'a', 'à' => 'a', 'â' => 'a', 'ã' => 'a', 'é' => 'e', 'ê' => 'e', 'í' => 'i', 'ó' => 'o', 'ô' => 'o', 'õ' => 'o', 'ú' => 'u', 'ç' => 'c']);
    }

    /** Chaves usadas pelo JavaScript, no formato de IdiomaService::script (chave completa => [pt, en, es]). */
    public static function js(): array
    {
        $out = [];
        foreach (self::JS as $k => $d) $out[self::GRUPO . '.js.' . $k] = ['pt' => $d[0], 'en' => $d[1], 'es' => $d[2]];
        return $out;
    }

    /** Script com os textos do JavaScript (window.greenT) — imprimir antes dos scripts das telas de NC. */
    public static function script(): string
    {
        return IdiomaService::script(['comum', self::GRUPO], self::js());
    }

